import{_ as p,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百一十一章 贪求生起种种获得","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/111第一百一十一章 贪求生起种种获得.md","filePath":"meditation/巴利文大藏经/111第一百一十一章 贪求生起种种获得.md"}'),o={name:"meditation/巴利文大藏经/111第一百一十一章 贪求生起种种获得.md"};function r(n,t,i,s,d,c){return _(),e("div",null,t[0]||(t[0]=[a('<h1 id="第一百一十一章-贪求生起种种获得" tabindex="-1">第一百一十一章 贪求生起种种获得 <a class="header-anchor" href="#第一百一十一章-贪求生起种种获得" aria-label="Permalink to &quot;第一百一十一章 贪求生起种种获得&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部14相应9经/外部的种种触经(界相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，以种种界（界解释，见第一百零八章）为前提条件生起种种念想，以种种念想为前提条件就会集中专注某种念想、思想。以种种集中专注的念想、思想为前提条件就会生起种种触（触解释，见第一百零四章），以种种触为前提条件就会生起种种感受，以种种感受为前提条件就会生起种种欲望，以种种欲望为前提条件就会生起种种渴爱、热爱，以种种渴爱、热爱为前提条件就会生起种种贪求，以种种贪求为前提条件就会生起种种获得。</p><p>弟子们，什么是种种界呢？就是：色界、声界、气味界、味道界、所触界、法界（色界、声界、气味界、味道界、所触界、法界解释，见第一百零八章），这些就被称为种种界。</p><p>弟子们，什么是以种种界为前提条件生起种种念想，以种种念想为前提条件就会集中专注某种念想、思想。以种种集中专注的念想、思想为前提条件就会生起种种触（触解释，见第一百零四章），以种种触为前提条件就会生起种种感受，以种种感受为前提条件就会生起种种欲望，以种种欲望为前提条件就会生起种种渴爱、热爱，以种种渴爱、热爱为前提条件就会生起种种贪求，以种种贪求为前提条件就会生起种种获得呢？</p><p>就是：以色界为前提条件生起对物质事物的种种念想，以对物质事物的种种念想为前提条件就会集中专注某种由物质事物生起的念想、思想。以种种集中专注某种由物质事物生起的念想、思想为前提条件就会分别出物质事物的存在和不同，并且产生对物质事物的认知，也就是生起色触。以色触为前提条件就会生起由色触引发产生的各种感受。以色触引发产生的各种感受为前提条件就会对物质事物生起种种的欲望，以对物质事物生起的种种欲望为前提条件就会对物质事物生起种种的渴爱、热爱，以对物质事物的种种渴爱、热爱为前提条件就会生起对物质事物的种种贪求。以对物质事物的种种贪求为前提条件就会生起对物质事物的种种获得。</p><p>以声界为前提条件生起对声音的种种念想，以对声音的种种念想为前提条件就会集中专注某种由声音生起的念想、思想。以种种集中专注某种由声音生起的念想、思想为前提条件就会分别出声音的存在和不同，并且产生对声音的认知，也就是生起声触。以声触为前提条件就会生起由声触引发产生的各种感受。以声触引发产生的各种感受为前提条件就会对声音生起种种的欲望，以对声音生起的种种欲望为前提条件就会对声音生起种种的渴爱、热爱，以对声音的种种渴爱、热爱为前提条件就会生起对声音的种种贪求。以对声音的种种贪求为前提条件就会生起对声音的种种获得。</p><p>以气味界为前提条件生起对气味的种种念想，以对气味的种种念想为前提条件就会集中专注某种由气味生起的念想、思想。以种种集中专注某种由气味生起的念想、思想为前提条件就会分别出气味的存在和不同，并且产生对气味的认知，也就是生起气味触。以气味触为前提条件就会生起由气味触引发产生的各种感受。以气味触引发产生的各种感受为前提条件就会对气味生起种种的欲望，以对气味生起的种种欲望为前提条件就会对气味生起种种的渴爱、热爱，以对气味的种种渴爱、热爱为前提条件就会生起对气味的种种贪求。以对气味的种种贪求为前提条件就会生起对气味的种种获得。</p><p>以味道界为前提条件生起对味道的种种念想，以对味道的种种念想为前提条件就会集中专注某种由味道生起的念想、思想。以种种集中专注某种由味道生起的念想、思想为前提条件就会分别出味道的存在和不同，并且产生对味道的认知，也就是生起味道触。以味道触为前提条件就会生起由味道触引发产生的各种感受。以味道触引发产生的各种感受为前提条件就会对味道生起种种的欲望，以对味道生起的种种欲望为前提条件就会对味道生起种种的渴爱、热爱，以对味道的种种渴爱、热爱为前提条件就会生起对味道的种种贪求。以对味道的种种贪求为前提条件就会生起对味道的种种获得。</p><p>以所触界为前提条件生起对触觉、环境（冷热、舒适等等特性）的种种念想，以对触觉、环境（冷热、舒适等等特性）的种种念想为前提条件就会集中专注某种由触觉、环境生起的念想、思想。以种种集中专注某种由触觉、环境生起的念想、思想为前提条件就会分别出触觉、环境的存在和不同，并且产生对触觉、环境的认知，也就是生起所触触。以所触触为前提条件就会生起由所触触引发产生的各种感受。以所触触引发产生的各种感受为前提条件就会对触觉、环境生起种种的欲望，以对触觉、环境生起的种种欲望为前提条件就会对触觉、环境生起种种的渴爱、热爱，以对触觉、环境的种种渴爱、热爱为前提条件就会生起对触觉、环境的种种贪求。以对触觉、环境的种种贪求为前提条件就会生起对触觉、环境的种种获得。</p><p>以法界为前提条件生起对物质事物、精神思想的种种念想，以对物质事物、精神思想的种种念想为前提条件就会集中专注某种由物质事物、精神思想生起的念想、思想。以种种集中专注某种由物质事物、精神思想生起的念想、思想为前提条件就会分别出物质事物、精神思想的存在和不同，并且产生对物质事物、精神思想的认知，也就是生起法触。以法触为前提条件就会生起由法触引发产生的各种感受。以法触引发产生的各种感受为前提条件就会对物质事物、精神思想生起种种的欲望，以对物质事物、精神思想生起的种种欲望为前提条件就会对物质事物、精神思想生起种种的渴爱、热爱，以对物质事物、精神思想的种种渴爱、热爱为前提条件就会生起对物质事物、精神思想的种种贪求。以对物质事物、精神思想的种种贪求为前提条件就会生起对物质事物、精神思想的种种获得。</p><p>弟子们，这就是以种种界为前提条件生起种种念想，以种种念想为前提条件就会集中专注某种念想、思想。以种种集中专注的念想、思想为前提条件就会生起种种触（触解释，见第一百零四章），以种种触为前提条件就会生起种种感受，以种种感受为前提条件就会生起种种欲望，以种种欲望为前提条件就会生起种种渴爱、热爱，以种种渴爱、热爱为前提条件就会生起种种贪求，以种种贪求为前提条件就会生起种种获得的法义。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',14)]))}const f=p(o,[["render",r]]);export{m as __pageData,f as default};
